def bbox(g,c):
    ps=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x==c]
    if not ps: return None
    return (min(p[0] for p in ps),max(p[0] for p in ps),min(p[1] for p in ps),max(p[1] for p in ps))
def solid(g,c):
    b=bbox(g,c)
