def max_nonzero_square(g):
    h,w=len(g),len(g[0]); nz=[[1 if g[i][j] else 0 for j in range(w)] for i in range(h)]
    best=0;pos=None
    for i in range(h):
        for j in range(w):
            k=1
            while i+k<=h and j+k<=w and all(nz[a][b] for a in range(i,i+k) for b in range(j,j+k)): k+=1
            if k-1>best: best=k-1; pos=(i,j)
    return best,pos
